SELECT \"nct\", \"author\", \"year\", \"pubmed_id\", \"trial_phase\", \"treatment_regimen\", \"name_of_ici\", \"class_of_ici\", \"monotherapy_combination\", \"type_of_combination\", \"control_regimen\", \"type_of_control\", \"cancer_type\" FROM public.\"clinical_trials\" WHERE \"trial_phase\" = 'Phase 2' AND \"class_of_ici\" = 'CTLA4' AND \"cancer_type\" = 'Pancreatic' AND \"type_of_combination\" IS NOT NULL;